// Independent auditor boundary, bundle and migration probe for PLAY-02.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import { boundaryContext, checkSource } from './scripts/check-boundaries.mjs';
import { client } from './packages/db/dist/index.js';

const MAIN = '6e9acf1';
const ctx = boundaryContext(process.cwd());
const owner = name => ctx.owners.find(o => o.name === name);
const browserOwners = ctx.owners.filter(o => ['browser', 'public'].includes(o.scope));
assert.deepEqual(browserOwners.map(o => o.name).sort(), ['@lorcana/contracts', '@lorcana/design-system', '@lorcana/engine-lab', '@lorcana/presentation', '@lorcana/web']);
const rel = (from, to) => { const a = from.split('/'), b = to.split('/'); let i = 0; while (a[i] === b[i]) i++; return '../'.repeat(a.length - i) + b.slice(i).join('/'); };
const privateTargets = ['@lorcana/engine-adapter', '@lorcana/engine-adapter/viewer', '@lorcana/engine-adapter/dist/viewer.js', '@lorcana/match-service', '@lorcana/db', '@lorcana/service-runtime', 'pg', 'node:crypto', 'node:worker_threads'];
const privateFiles = ['packages/engine-adapter/src/viewer.ts', 'packages/engine-adapter/src/viewer-intent.ts', 'packages/engine-adapter/src/replay.ts', 'packages/engine-adapter/src/persistence.ts', 'packages/engine-adapter/dist/viewer.js', 'apps/match-service/src/engine-executor.ts', 'apps/match-service/src/service.ts', 'apps/match-service/src/transition-worker.ts'];
const forms = s => [`import x from '${s}';`, `export * from '${s}';`, `const m = await import('${s}');`, `import type { X } from '${s}';`];
let refused = 0;
for (const o of browserOwners) {
  const file = join(o.path, 'src', 'audit-virtual.ts');
  for (const target of [...privateTargets, ...privateFiles.map(f => rel(join(o.path, 'src'), join(ctx.root, f)))]) for (const code of forms(target)) {
    assert.throws(() => checkSource(file, ctx, code), /Forbidden/, o.name + ' accepted ' + code); refused++;
  }
  checkSource(file, ctx, `import { decodeViewerProjection, decodeViewerSurface } from '@lorcana/contracts';`); // browser-safe codec stays importable
}
let serverRefused = 0;
for (const name of ['@lorcana/match-service', '@lorcana/db', '@lorcana/api', '@lorcana/worker', '@lorcana/service-runtime']) {
  const file = join(owner(name).path, 'src', 'audit-virtual.ts');
  for (const target of ['@lorcana/vendor-engine', '@lorcana/engine-lab', rel(join(owner(name).path, 'src'), join(ctx.root, 'vendor/tcg-engines/dist/kernel.js'))]) for (const code of forms(target)) {
    assert.throws(() => checkSource(file, ctx, code), /Forbidden/, name + ' accepted ' + code); serverRefused++;
  }
}
for (const f of readdirSync('apps/match-service/src')) assert.equal(/@lorcana\/vendor-engine|@lorcana\/engine-lab|\/vendor\/|engine-adapter\/src/.test(readFileSync('apps/match-service/src/' + f, 'utf8')), false, f);
// Lab never invokes the new private inspection hook; the only occurrence is the bundled kernel's definition.
for (const f of readdirSync('packages/engine-lab/src')) assert.equal(/inspect/.test(readFileSync(join('packages/engine-lab/src', f), 'utf8')), false, 'Lab source mentions inspect: ' + f);
const labWorker = readFileSync('packages/engine-lab/dist/lab-worker.js', 'utf8');
assert.equal((labWorker.match(/inspect\(/g) ?? []).length, 1); assert.equal(/\.inspect\(|\["inspect"\]|'inspect'|"inspect"/.test(labWorker), false, 'Lab worker calls inspect');
assert.ok(labWorker.includes('MOVE_FORBIDDEN'));
// Shipped browser and Lab bundles carry no server viewer/ref/checkpoint material.
const files = dir => readdirSync(dir, { withFileTypes: true }).flatMap(e => e.isDirectory() ? files(join(dir, e.name)) : [join(dir, e.name)]);
const webFiles = files('apps/web/dist').filter(f => /\.(js|html|css|map)$/.test(f)), labFiles = files('packages/engine-lab/dist').filter(f => f.endsWith('.js'));
const markers = ['private-viewer-key-v1', 'viewer-ref-v1', 'createViewerProjection', 'resolveViewerIntent', 'Reference rejected', 'Viewer unavailable', 'normalInkTargets', 'private-match-checkpoint-v1', 'restorePrivateMatch', 'createMatchRepository', 'match.command_receipts', 'synthetic-play01', 'createEngineExecutor', 'server-match-seed-v1', 'completed-private-replay-v1', 'lorcana_test_match', 'lorcana_local_match'];
for (const f of [...webFiles, ...labFiles]) { const t = readFileSync(f, 'utf8'); for (const m of markers) assert.equal(t.includes(m), false, f + ' contains ' + m); }
assert.equal(webFiles.some(f => /manualSetLore|createSyntheticKernel|getPublishedGameEvents/.test(readFileSync(f, 'utf8'))), false, 'web bundle contains engine code');
// Vendor change is confined to the project-owned bridge; upstream sources, patches and engine tooling are byte-identical to main.
const vendorDiff = execFileSync('git', ['diff', '--name-only', MAIN, 'HEAD', '--', 'vendor/', 'scripts/engine/']).toString().trim().split('\n').sort();
assert.deepEqual(vendorDiff, ['vendor/tcg-engines/README.md', 'vendor/tcg-engines/src/kernel.d.ts', 'vendor/tcg-engines/src/kernel.ts']);
const bridge = execFileSync('git', ['diff', MAIN, 'HEAD', '--', 'vendor/tcg-engines/src/kernel.ts']).toString().split('\n').filter(l => /^[+-][^+-]/.test(l));
assert.equal(bridge.length, 2); assert.ok(bridge.every(l => l.startsWith('+')), 'bridge removed lines');
const kernel = readFileSync('vendor/tcg-engines/dist/kernel.js'), kernelBytes = statSync('vendor/tcg-engines/dist/kernel.js').size, kernelSha = createHash('sha256').update(kernel).digest('hex');
// The worker still drains upstream console output and strips credential-like environment.
const exec = readFileSync('apps/match-service/dist/engine-executor.js', 'utf8');
assert.ok(/stdout\.resume\(\)/.test(exec) && /stderr\.resume\(\)/.test(exec) && exec.includes('password|secret|token|credential|private_key') && exec.includes('PG|POSTGRES|DATABASE'));
// No new migration; 0001–0003 byte-identical to main; histories and match-table privileges unchanged in both databases.
const migrations = readdirSync('packages/db/migrations').sort();
assert.deepEqual(migrations, ['0001-foundation-probes.sql', '0002-match-commands.sql', '0003-match-receipt-invariants.sql']);
const sha = b => createHash('sha256').update(b).digest('hex');
const expected = migrations.map(name => { const b = readFileSync('packages/db/migrations/' + name); assert.equal(sha(execFileSync('git', ['show', MAIN + ':packages/db/migrations/' + name])), sha(b), name + ' changed since main'); return [name.slice(0, 4), sha(b)]; });
const tables = ['releases', 'matches', 'command_receipts', 'journal', 'outbox'], db = {};
for (const target of ['local', 'test']) {
  const c = client(target, 'migrator'); await c.connect();
  try {
    assert.deepEqual((await c.query('SELECT id,sha256 FROM foundation.migrations ORDER BY id')).rows.map(r => [r.id, r.sha256]), expected, target + ' history');
    for (const t of tables) {
      for (const [role, all] of [['match', true], ['api', false], ['worker', false]]) {
        const p = (await c.query("SELECT has_table_privilege($1,$2,'SELECT') s, has_table_privilege($1,$2,'INSERT') i, has_table_privilege($1,$2,'UPDATE') u, has_table_privilege($1,$2,'DELETE') d", [`lorcana_${target}_${role}`, 'match.' + t])).rows[0];
        assert.deepEqual([p.s, p.i, p.u, p.d], [all, all, all, all], target + ' ' + role + ' ' + t);
      }
      assert.equal((await c.query("SELECT count(*)::int n FROM information_schema.role_table_grants WHERE table_schema='match' AND table_name=$1 AND grantee='PUBLIC'", [t])).rows[0].n, 0);
    }
    db[target] = (await c.query('SELECT count(*)::int n FROM foundation.migrations')).rows[0].n;
  } finally { await c.end(); }
}
console.log(JSON.stringify({ browserOwners: browserOwners.length, browserImportsRefused: refused, serverKernelImportsRefused: serverRefused, webFilesScanned: webFiles.length, labFilesScanned: labFiles.length, markers: markers.length, vendorDiff, kernelBytes, kernelSha, migrations: expected.map(([i, h]) => i + ':' + h.slice(0, 12)), db }));
console.log('PASS auditor PLAY-02 boundary/bundle/migration probe: five browser/public owners refuse static/dynamic/re-export/type imports of the adapter (including viewer subpaths), match service, db, runtime, pg, Node crypto/workers and relative paths to projector/resolver/replay/persistence/executor/service/worker sources while the closed viewer codec stays importable; non-adapter server owners cannot reach the kernel/Lab; Lab never calls the new inspection hook; web and Lab bundles carry no projector/ref-key/checkpoint/server markers; vendor change is the two-line project bridge only; no migration added and both database histories/privileges unchanged');
